INSERT INTO genome_samples (sample_id, plant_latin_name, population_code, region, collection_method, non_destructive, date_collected, storage) VALUES
('GS_COL_0001', 'Pogostemon cablin', 'COL_Pop_A', 'Colombia', 'pollen', TRUE, '2026-01-06', 'silica_gel');

