('GCMS_0001', 'HB_0001', 'HS-SPME-GC-MS', '2026-01-06', '["linalool", "camphor", "1,8-cineole"]', '[{"name":"linalool","cas":"78-70-6","percent":32.1}]', 'seed');

-- Manuscript (AX2)
INSERT INTO perfumum_manuscripts (manuscript_id, title, language, date_range, repository, region, license, ocr_status, tags) VALUES
('MS_OTTOMAN_0001', 'Recueil de recettes d''encens (exemple)', 'Ottoman Turkish', '1600-1700', 'Topkapi Palace Library', 'Ottoman', 'Unknown', 'queued', '["incense", "trade", "resins"]');

-- Text Fragment (AX2)
INSERT INTO text_fragments (fragment_id, manuscript_id, language, original_text, translation_fr, entities, evidence_level, notes) VALUES
('FRAG_0001', 'MS_OTTOMAN_0001', 'Ottoman Turkish', '...', '...', '[{"type":"plant","value":"Cistus","confidence":0.62}]', 'hypothetical', 'seed example');

-- Trade Route (AX2)
INSERT INTO trade_routes (route_id, name, time_start, time_end, nodes, materials, notes) VALUES
('TR_001', 'Route résines Méditerranée → Istanbul', 500, 1700, '[{"place":"Chios","lat":38.37,"lon":26.14,"role":"source"},{"place":"Istanbul","lat":41.01,"lon":28.97,"role":"hub"}]', '["mastic", "labdanum", "frankincense"]', 'seed example');

-- Tissue Culture Line (AX4)
INSERT INTO tissue_culture_lines (line_id, plant_latin_name, origin, method, status, storage) VALUES
('TCL_0001', 'Jasminum grandiflorum', 'Grasse-form (historic)', 'meristem', 'active', 'in_vitro');

-- Fermentation Run (AX4)
INSERT INTO perfumum_fermentation_runs (run_id, target_molecule, host, gene_source, bioreactor_l, yield_g_l, purity_percent, notes) VALUES
('FERM_0001', 'patchoulol', 'S_cerevisiae', 'Pogostemon cablin TPS', 5.00, 0.8000, 92.00, 'directed fermentation seed');

-- VR Scene (AX5)
INSERT INTO vr_scenes (scene_id, title, era, location, assets, scent_cues, hardware) VALUES
('VR_0001', 'Roseraie ottomane — promenade', '17th century', 'Istanbul', '["garden.glb", "ambience.wav"]', '[{"time_s":10,"blend_id":"BLEND_ROSE_RESIN","intensity":0.7,"notes":"entry"}]', 'webxr + diffuser api');

-- Citizen Observation (AX5)
INSERT INTO citizen_observations (obs_id, user_handle, plant_guess, lat, lon, obs_date, confidence_ai, status, notes) VALUES
('OBS_0001', '@field_scientist', 'Bursera graveolens', 12.584000, -81.700000, '2026-01-06', 0.56, 'submitted', 'San Andrés seed');

-- Partner Institution (AX6)
INSERT INTO partner_institutions (partner_id, name, country, type, focus, mou_status) VALUES
('P_KEW', 'Royal Botanic Gardens, Kew', 'UK', 'botanic_garden', '["conservation", "seedbank", "taxonomy"]', 'idea');

-- Fellowship (AX6)
INSERT INTO perfumum_fellowships (fellowship_id, title, region_focus, duration_months, budget_chf, deliverables, selection_criteria, status) VALUES
('FEL_0001', 'Gardiens du patrimoine olfactif — Andean Botanics', 'Colombia', 12, 25000, '["dataset", "protocol", "co-publication", "field_samples"]', '["local_researcher", "ethics", "open_data"]', 'draft');

